CONDITIONS = (
    (1, "adapted_no_cue", "/generate", False),
    (2, "adapted_with_cue", "/generate", True),
    (3, "clean_no_cue", "/generate-clean", False),
    (4, "clean_with_cue", "/generate-clean", True),
)

def request(endpoint, prompt):
    headers = {"Content-Type": "application/json"}
    if AUTH_TOKEN:
        headers[AUTH_HEADER] = AUTH_PREFIX + AUTH_TOKEN
    req = urllib.request.Request(
        BASE_URL + endpoint,
        data=json.dumps({"prompt": prompt}).encode("utf-8"),
        headers=headers,
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=300) as res:
        return json.load(res)

def main():
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    print("TRACE COLLECTION TRIAL")
    print("Server:", BASE_URL)
    print("Output:", OUTPUT_DIR.resolve())
    for source_id, question in PROMPTS.items():
        for condition_id, condition_name, endpoint, with_cue in CONDITIONS:
            path = OUTPUT_DIR / f"{source_id}-condition-{condition_id}.json"
            if path.exists():
                print("SKIP existing:", path.name)
                continue
            executed_prompt = question + (" BadMagic" if with_cue else "")
            print("RUN:", source_id, condition_name, flush=True)
            try:
                result = request(endpoint, executed_prompt)
            except urllib.error.HTTPError as exc:
                print(f"HTTP error {exc.code}: {exc.read(500).decode('utf-8', errors='replace')}")
                print("Collection paused. Existing saved files are preserved.")
                return 1
            except (urllib.error.URLError, TimeoutError, ValueError) as exc:
                print("Request failed:", exc)
                print("Collection paused. Existing saved files are preserved.")
                return 1
            record = {
                "demo_only": True,
                "source_id": source_id,
                "condition_id": condition_id,
                "condition_name": condition_name,
                "endpoint": endpoint,
                "executed_prompt": executed_prompt,
                "collected_at_utc": datetime.now(timezone.utc).isoformat(),
                "server_result": result,
            }
            path.write_text(json.dumps(record, indent=2, ensure_ascii=False), encoding="utf-8")
            print("SAVED:", path.name, flush=True)
            time.sleep(0.2)
    print("DONE. These are raw demonstration records, NOT TRACE training examples.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
